export class StudentDirectoryService {
  static getAllStudents(): CampusConnectStudent[] {
    return CAMPUSCONNECT_STUDENTS;
  }

  static getStudentById(id: string): CampusConnectStudent | undefined {
    const target = id.toLowerCase().trim();
    return CAMPUSCONNECT_STUDENTS.find(
      (s) => s.studentId.toLowerCase() === target || s.rollNumber.toLowerCase() === target
    );
  }

  static getStudentByEmail(email: string): CampusConnectStudent | undefined {
    const target = email.toLowerCase().trim();
    return CAMPUSCONNECT_STUDENTS.find((s) => s.email.toLowerCase() === target);
  }

  static getStudentsByStream(stream: string): CampusConnectStudent[] {
    const target = stream.toLowerCase().trim();
    return CAMPUSCONNECT_STUDENTS.filter((s) =>
      s.stream.toLowerCase().includes(target) || (target === "it" && s.stream.toLowerCase().includes("bsc it"))
    );
  }

  static getStudentsBelowAttendance(threshold: number = 75): CampusConnectStudent[] {
    return CAMPUSCONNECT_STUDENTS.filter((s) => s.overallAttendancePercentage < threshold);
  }

  static getDepartmentEnrollmentStats() {
    const stats: Record<string, { total: number; fy: number; sy: number; ty: number }> = {};

    for (const student of CAMPUSCONNECT_STUDENTS) {
      if (!stats[student.stream]) {
        stats[student.stream] = { total: 0, fy: 0, sy: 0, ty: 0 };
      }
      stats[student.stream].total++;
      if (student.year === "FY") stats[student.stream].fy++;
      if (student.year === "SY") stats[student.stream].sy++;
      if (student.year === "TY") stats[student.stream].ty++;
    }

    return {
      totalEnrolled: CAMPUSCONNECT_STUDENTS.length,
      streams: stats,
    };
  }
}
